generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math word problem step by step. Write all reasoning in plain text. At the end, write ONLY the final arithmetic expression (using +, -, *, /, //, (, ) and variable names) inside << >>. No LaTeX, no backticks, no dollar signs, no curly braces inside << >>.";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
  // prefixBudget: allow up to 2/3 of budget for reasoning before forcing span entry
  var prefixBudget: nat := (maxSteps * 2) / 3;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var boostAmount: real := 4.0;
  var narrowThreshold: nat := 12;

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, boostAmount, narrowThreshold, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}

// CSD_RATIONALE_BEGIN
