  if reasoningBudget >= maxSteps { reasoningBudget := maxSteps - 1; }

  // Use UnconstrainedChunk to generate reasoning until << appears or budget exhausted
  while steps < reasoningBudget && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases reasoningBudget - steps
  {
    var chunkBudget: nat := reasoningBudget - steps;
    if chunkBudget > 32 { chunkBudget := 32; }

    var genOut, stoppedOnOpen, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );

    steps := steps + stepsUsed;
    generated := genOut;

    if stoppedOnEos {
      break;
    } else if stoppedOnOpen {
      // << was naturally emitted, enter constrained mode
      var g2, ic2, cc2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := ic2;
      currentConstrainedOut := cc2;
      break;
    }
    // Otherwise chunk budget was exhausted, loop continues
  }

  // If we haven't entered a constrained span yet, force open one
  if !insideConstrainedOut && steps < maxSteps {
    var g2, ic2, cc2 := helpers.OpenConstrainedSpan(lm, generated);
    generated := g2;
    insideConstrainedOut := ic2;
    currentConstrainedOut := cc2;
    steps := steps + 1;
  }

  // Phase 2: If inside constrained span, use CloseSpanWithinBudget to fill and close
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget: nat := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }

  // Phase 3: If span was closed and we have budget left, allow additional free generation
  // This handles cases where the model might want to write more after the answer
  if !insideConstrainedOut && steps < maxSteps {
    var remainingBudget: nat := maxSteps - steps;
    // Use ManagedStep for remaining budget - handles any additional spans gracefully
    var innerSteps: nat := 0;
    while innerSteps < remainingBudget
      invariant 0 <= innerSteps <= remainingBudget
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps + innerSteps
      decreases remainingBudget - innerSteps
    {
      var g2, ic2, cc2, done := helpers.ManagedStep(
        lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
        validTokenGroups, 4.0, 12, eosToken
      );
      generated := g2;
      insideConstrainedOut := ic2;
      currentConstrainedOut := cc2;
      innerSteps := innerSteps + 1;
      if done {
        break;
      }
    }
    steps := steps + innerSteps;
  }

  cost := steps;
}

